declare(strict_types=1);$config=require __DIR__.'/../config/config.php';header('Content-Type:text/plain; charset=utf-8');if(str_contains($config['pesapal']['consumer_key'],'YOUR_PESAPAL'))die("Add PesaPal consumer_key and consumer_secret first.\n");$base=$config['pesapal']['environment']==='live'?'https://pay.pesapal.com/v3':'https://cybqa.pesapal.com/pesapalv3';function req($url,$payload,$token=null){$ch=curl_init($url);$h=['Accept: application/json','Content-Type: application/json'];if($token)$h[]='Authorization: Bearer '.$token;curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>$h,CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode((string)$raw,true);if($code<200||$code>=300)die("Provider error: ".($d['error']['message']??$raw));return $d;}$a=req($base.'/api/Auth/RequestToken',['consumer_key'=>$config['pesapal']['consumer_key'],'consumer_secret'=>$config['pesapal']['consumer_secret']]);$r=req($base.'/api/URLSetup/RegisterIPN',['url'=>$config['pesapal']['ipn_url'],'ipn_notification_type'=>'POST'],$a['token']??null);echo "IPN registered.\nIPN ID: ".($r['ipn_id']??'NOT RETURNED')."\n\nPut this IPN ID into config/config.php as notification_id.\n";
